#!/usr/bin/env bash

if [ $# -lt 1 ]; then
    echo "Need argument to specify the voir executable"
    exit -1
fi

VOIR="${1}"

echo "VOIR = ${VOIR}"

# Input files generated by generate_fst (RSF + XDF variants).
test_file_in_rsf=03_voir_basic_in.rsf
test_file_in_xdf=03_voir_basic_in.xdf

# Distinctive metadata that must appear in voir's table of contents.
etikets=("VOIR_ETI_1" "VOIR_ETI_2" "VOIR_ETI_3")

# Run voir on a valid file and check that the table of contents is printed.
function run_happy_path() {
    test_file_in=${1}
    if ! [ -f ${test_file_in} ]; then
        echo "Test FST file ${test_file_in} does not exist!"
        exit -1
    fi

    output=$(${VOIR} -iment ${test_file_in} 2>&1)
    rc=$?
    if [ ${rc} -ne 0 ]; then
        echo "voir -iment ${test_file_in} returned non-zero exit code ${rc}:"
        echo "${output}"
        exit -1
    fi

    # The summary line proves records were actually read from the file.
    if ! echo "${output}" | grep -q "records in RPN standard file"; then
        echo "Missing 'records in RPN standard file' summary line in voir output:"
        echo "${output}"
        exit -1
    fi

    # Each record's etiket must be listed in the table of contents.
    for etiket in "${etikets[@]}"; do
        if ! echo "${output}" | grep -q "${etiket}"; then
            echo "Missing etiket ${etiket} in voir output:"
            echo "${output}"
            exit -1
        fi
    done
}

echo "=== Happy path (RSF) ==="
run_happy_path ${test_file_in_rsf}

echo "=== Happy path (XDF) ==="
run_happy_path ${test_file_in_xdf}

echo "=== Help (-morehelp) ==="
help_output=$(${VOIR} -morehelp 2>&1)
if ! echo "${help_output}" | grep -q "VOIR CALLING SEQUENCE"; then
    echo "Missing 'VOIR CALLING SEQUENCE' in -morehelp output:"
    echo "${help_output}"
    exit -1
fi

echo "=== Error (nonexistent file) ==="
missing_file=03_voir_does_not_exist_${$}.rsf
err_output=$(${VOIR} -iment ${missing_file} 2>&1)
err_rc=$?
if [ ${err_rc} -eq 0 ]; then
    echo "voir -iment ${missing_file} should have failed but returned 0:"
    echo "${err_output}"
    exit -1
fi

echo "All voir tests passed."
exit 0
